def max_happiness(N, friday_matrix, saturday_matrix):
    def calculate_happiness(employees, clubs, matrix):
        return sum(matrix[employee][club] for employee, club in zip(employees, clubs))

    total_happiness = 0
    employees = list(range(N))
    visited_groups = set()

    for perm in permutations(employees):
        friday_employees = tuple(sorted(perm[:N//2]))
        if friday_employees in visited_groups:
            continue
        visited_groups.add(friday_employees)

        friday_employees = list(perm[:N//2])
        saturday_employees = list(perm[N//2:])

        for friday_clubs in permutations(range(N), N//2):
            unvisited_clubs = set(range(N)) - set(friday_clubs)
            for saturday_clubs in permutations(unvisited_clubs, N//2):
                fridays_happiness = calculate_happiness(friday_employees, friday_clubs, friday_matrix)
                saturdays_happiness = calculate_happiness(saturday_employees, saturday_clubs, saturday_matrix)
                total_happiness = max(total_happiness, fridays_happiness + saturdays_happiness)

    return total_happiness

